('Material Request Receipt Notification','2019-04-29 11:53:23.981418','2019-05-01 18:02:51.090037','Administrator','Administrator',0,0,1,'Email',NULL,'{{ doc.name }} has been received','Material Request',1,'Manufacturing','Value Change','',NULL,0,'status',NULL,0,'','doc.status == \"Received\" or doc.status == \"Partially Received\"',NULL,NULL,0,'<b>Material Request Type</b>: {{ doc.material_request_type }}<br>\n<b>Company</b>: {{ doc.company }}\n\n<h3>Order Summary</h3>\n\n<table border=2 >\n    <tr align=\"center\">\n        <th>Item Name</th>\n        <th>Received Quantity</th>\n    </tr>\n    {% for item in doc.items %}\n        {% if frappe.utils.flt(item.received_qty, 2) > 0.0 %}\n            <tr align=\"center\">\n                <td>{{ item.item_code }}</td>\n                <td>{{ frappe.utils.flt(item.received_qty, 2) }}</td>\n            </tr>\n        {% endif %}\n    {% endfor %}\n</table>',0,NULL,NULL,NULL,NULL,NULL),
('Notification for new fiscal year','2018-04-25 14:19:05.440361','2018-04-25 14:30:38.588534','Administrator','Administrator',0,0,1,'Email',NULL,'Notification for new fiscal year {{ doc.name }}','Fiscal Year',1,'Accounts','New',NULL,NULL,0,NULL,NULL,0,NULL,'doc.auto_created',NULL,NULL,0,'<h3>{{_(\"Fiscal Year\")}}</h3>\n\n<p>{{ _(\"New fiscal year created :- \") }} {{ doc.name }}</p>',0,NULL,NULL,NULL,NULL,NULL);
